// +=================================+
// | Distribution Properties         |
// +=================================+

// returns the lowest value of the NGrid,
// across all dimensions
float_t NGrid::min() const {

	// static resources: only create once
	static ShaderModule shader(manager->get_device(), MIN_SPIRV_BIN, MIN_SPIRV_BYTES);
	static DescriptorSetLayout set_layout = DescriptorSetLayout(manager->get_device());
	static bool layout_initialized = false;
	if (!layout_initialized) {
		set_layout.add_bindings(2, DescriptorType::STORAGE_BUFFER_DESCRIPTOR);
		set_layout.finalize();
		layout_initialized = true;
	}
	static ComputePipeline pipeline(manager->get_device(), shader, sizeof(uint32_t), set_layout, workgroup_size_1d, 1, 1); // sizeof(uint32_t) is used because the push_constants only have a single value (=elements_A), which is type uint32_t

	// calculate the required number of workgroups for the first iteration
	uint32_t elements_A = this->elements; // elements in the input buffer (will be 'buffer_A')
	uint32_t num_workgroups = (elements_A + workgroup_size_1d - 1) / workgroup_size_1d;

	// create temporary buffers on "main_task" (this task only holds the resources; it has no command buffer)
	ComputeTask& main_task = manager->get_compute_task(__FUNCTION__);
	Buffer<float_t>& buffer_A = main_task.add_temp_buffer<float_t>(this->elements, BufferUsage::STORAGE_BUFFER, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
	Buffer<float_t>& buffer_B = main_task.add_temp_buffer<float_t>(num_workgroups, BufferUsage::STORAGE_BUFFER, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
	Buffer<float_t>* input_buffer = &buffer_A;			// =initialization; buffers A and B will take part in a repeated ping-pong swap later in the main loop
	Buffer<float_t>* local_results_buffer = &buffer_B;  // "  "  " 
	Buffer<float_t>& final_result_staging_buffer = main_task.add_temp_buffer<float_t>(1, BufferUsage::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);

	uint32_t iteration = 0;

	do {
		// acquire an idle compute task (=one for each iteration)
		ComputeTask& task = manager->get_compute_task(__FUNCTION__);

		// define push constants (transient resource, owned by the task)
		PushConstants& constants = task.add_constants(
			elements_A
		);

		// add a descriptor set (transient resource, owned by the task)
		DescriptorSet& ds = task.add_descriptor_set(set_layout);
		ds.bind_buffer(0, *input_buffer);
		ds.bind_buffer(1, *local_results_buffer);
		ds.write();

		// begin command buffer recording
		CommandBuffer& cb = task.get_command_buffer();
		cb.begin_recording();
		cb.bind_pipeline(pipeline);
		cb.bind_descriptor_set(ds, pipeline);
		cb.bind_push_constants(constants, pipeline);

		// first iteration: copy source data to input buffer
		if (iteration == 0) {
			cb.add_buffer_memory_barrier(this->get_buffer(), VK_ACCESS_2_SHADER_WRITE_BIT | VK_ACCESS_2_SHADER_READ_BIT | VK_ACCESS_2_TRANSFER_WRITE_BIT | VK_ACCESS_2_TRANSFER_READ_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
			cb.record_barriers();
			cb.copy_buffer(this->get_buffer(), *input_buffer);
			cb.add_buffer_memory_barrier(*input_buffer, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_SHADER_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT);
			cb.record_barriers();
		}

		// pipeline dispatch
		cb.dispatch(pipeline, elements_A, 1, 1);

		// final iteration
		if (num_workgroups == 1) {
			// copy final result to staging buffer to allow host visibility
			cb.add_buffer_memory_barrier<float_t>(*local_results_buffer, VK_ACCESS_2_SHADER_WRITE_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
			cb.record_barriers();
			cb.copy_buffer(*local_results_buffer, final_result_staging_buffer, sizeof(float_t), 0, 0);
			cb.add_buffer_memory_barrier(final_result_staging_buffer, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_HOST_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_HOST_BIT);
			cb.record_barriers();
		}

		// all other iterations
		else {
			input_buffer = input_buffer == &buffer_A ? &buffer_B : &buffer_A;					// ping-pong swap
			local_results_buffer = local_results_buffer == &buffer_A ? &buffer_B : &buffer_A;	// "   "   "
		}

		cb.end_recording();
		task.timeline_sync(*timeline_semaphore);

		// ensure that the final result copy has finished before reading back from the staging buffer
		if (num_workgroups == 1) {
			task.submit(1e09); // = wait for fence
		}
		else {
			task.submit();
		}

		elements_A = num_workgroups;
		num_workgroups = (elements_A + workgroup_size_1d - 1) / workgroup_size_1d;
		iteration++;

	} while (num_workgroups > 1);

	main_task.get_command_buffer(); // empty command buffer, just to trigger a fence signaling completion
	uint64_t finished_counter = main_task.timeline_sync(*timeline_semaphore);
	this->set_tasks_finished_semaphore_counter(finished_counter);
	main_task.submit(5e09);
	float_t result = final_result_staging_buffer.read_element(0);
	return result;
}

// returns the highest value of the NGrid,
// across all dimensions
float_t NGrid::max() const {

	// static resources: only create once
	static ShaderModule shader(manager->get_device(), MAX_SPIRV_BIN, MAX_SPIRV_BYTES);
	static DescriptorSetLayout set_layout = DescriptorSetLayout(manager->get_device());
	static bool layout_initialized = false;
	if (!layout_initialized) {
		set_layout.add_bindings(2, DescriptorType::STORAGE_BUFFER_DESCRIPTOR);
		set_layout.finalize();
		layout_initialized = true;
	}
	static ComputePipeline pipeline(manager->get_device(), shader, sizeof(uint32_t), set_layout, workgroup_size_1d, 1, 1); // sizeof(uint32_t) is used because the push_constants only have a single value (=elements_A), which is type uint32_t

	// calculate the required number of workgroups for the first iteration
	uint32_t elements_A = this->elements; // elements in the input buffer (will be 'buffer_A')
	uint32_t num_workgroups = (elements_A + workgroup_size_1d - 1) / workgroup_size_1d;

	// create temporary buffers on "main_task" (this task only holds the resources; it has no command buffer)
	ComputeTask& main_task = manager->get_compute_task(__FUNCTION__);
	Buffer<float_t>& buffer_A = main_task.add_temp_buffer<float_t>(this->elements, BufferUsage::STORAGE_BUFFER, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
	Buffer<float_t>& buffer_B = main_task.add_temp_buffer<float_t>(num_workgroups, BufferUsage::STORAGE_BUFFER, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
	Buffer<float_t>* input_buffer = &buffer_A;			// =initialization; buffers A and B will take part in a repeated ping-pong swap later in the main loop
	Buffer<float_t>* local_results_buffer = &buffer_B;  // "  "  " 
	Buffer<float_t>& final_result_staging_buffer = main_task.add_temp_buffer<float_t>(1, BufferUsage::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);

	uint32_t iteration = 0;

	do {
		// acquire an idle compute task (=one for each iteration)
		ComputeTask& task = manager->get_compute_task(__FUNCTION__);

		// define push constants (transient resource, owned by the task)
		PushConstants& constants = task.add_constants(
			elements_A
		);

		// add a descriptor set (transient resource, owned by the task)
		DescriptorSet& ds = task.add_descriptor_set(set_layout);
		ds.bind_buffer(0, *input_buffer);
		ds.bind_buffer(1, *local_results_buffer);
		ds.write();

		// begin command buffer recording
		CommandBuffer& cb = task.get_command_buffer();
		cb.begin_recording();
		cb.bind_pipeline(pipeline);
		cb.bind_descriptor_set(ds, pipeline);
		cb.bind_push_constants(constants, pipeline);

		// first iteration: copy source data to input buffer
		if (iteration == 0) {
			cb.add_buffer_memory_barrier(this->get_buffer(), VK_ACCESS_2_SHADER_WRITE_BIT | VK_ACCESS_2_SHADER_READ_BIT | VK_ACCESS_2_TRANSFER_WRITE_BIT | VK_ACCESS_2_TRANSFER_READ_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
			cb.record_barriers();
			cb.copy_buffer(this->get_buffer(), *input_buffer);
			cb.add_buffer_memory_barrier(*input_buffer, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_SHADER_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT);
			cb.record_barriers();
		}

		// pipeline dispatch
		cb.dispatch(pipeline, elements_A, 1, 1);

		// final iteration
		if (num_workgroups == 1) {
			// copy final result to staging buffer to allow host visibility
			cb.add_buffer_memory_barrier<float_t>(*local_results_buffer, VK_ACCESS_2_SHADER_WRITE_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
			cb.record_barriers();
			cb.copy_buffer(*local_results_buffer, final_result_staging_buffer, sizeof(float_t), 0, 0);
			cb.add_buffer_memory_barrier(final_result_staging_buffer, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_HOST_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_HOST_BIT);
			cb.record_barriers();
		}

		// all other iterations
		else {
			input_buffer = input_buffer == &buffer_A ? &buffer_B : &buffer_A;					// ping-pong swap
			local_results_buffer = local_results_buffer == &buffer_A ? &buffer_B : &buffer_A;	// "   "   "
		}

		cb.end_recording();
		task.timeline_sync(*timeline_semaphore);

		// ensure that the final result copy has finished before reading back from the staging buffer
		if (num_workgroups == 1) {
			task.submit(1e09); // = wait for fence
		}
		else {
			task.submit();
		}

		elements_A = num_workgroups;
		num_workgroups = (elements_A + workgroup_size_1d - 1) / workgroup_size_1d;
		iteration++;

	} while (num_workgroups > 1);

	main_task.get_command_buffer(); // empty command buffer, just to trigger a fence signaling completion
	uint64_t finished_counter = main_task.timeline_sync(*timeline_semaphore);
	this->set_tasks_finished_semaphore_counter(finished_counter);
	main_task.submit(5e09);
	float_t result = final_result_staging_buffer.read_element(0);
	return result;
}

// returns the value of the NGrid with the highest
// deviation from zero, across all dimensions
float_t NGrid::maxabs() const {

	// static resources: only create once
	static ShaderModule shader(manager->get_device(), MAXABS_SPIRV_BIN, MAXABS_SPIRV_BYTES);
	static DescriptorSetLayout set_layout = DescriptorSetLayout(manager->get_device());
	static bool layout_initialized = false;
	if (!layout_initialized) {
		set_layout.add_bindings(2, DescriptorType::STORAGE_BUFFER_DESCRIPTOR);
		set_layout.finalize();
		layout_initialized = true;
	}
	static ComputePipeline pipeline(manager->get_device(), shader, sizeof(uint32_t), set_layout, workgroup_size_1d, 1, 1); // sizeof(uint32_t) is used because the push_constants only have a single value (=elements_A), which is type uint32_t

	// calculate the required number of workgroups for the first iteration
	uint32_t elements_A = this->elements; // elements in the input buffer (will be 'buffer_A')
	uint32_t num_workgroups = (elements_A + workgroup_size_1d - 1) / workgroup_size_1d;

	// create temporary buffers on "main_task" (this task only holds the resources; it has no command buffer)
	ComputeTask& main_task = manager->get_compute_task(__FUNCTION__);
	Buffer<float_t>& buffer_A = main_task.add_temp_buffer<float_t>(this->elements, BufferUsage::STORAGE_BUFFER, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
	Buffer<float_t>& buffer_B = main_task.add_temp_buffer<float_t>(num_workgroups, BufferUsage::STORAGE_BUFFER, VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT);
	Buffer<float_t>* input_buffer = &buffer_A;			// =initialization; buffers A and B will take part in a repeated ping-pong swap later in the main loop
	Buffer<float_t>* local_results_buffer = &buffer_B;  // "  "  " 
	Buffer<float_t>& final_result_staging_buffer = main_task.add_temp_buffer<float_t>(1, BufferUsage::TRANSFER_BUFFER, VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT | VK_MEMORY_PROPERTY_HOST_COHERENT_BIT);

	uint32_t iteration = 0;

	do {
		// acquire an idle compute task (=one for each iteration)
		ComputeTask& task = manager->get_compute_task(__FUNCTION__);

		// define push constants (transient resource, owned by the task)
		PushConstants& constants = task.add_constants(
			elements_A
		);

		// add a descriptor set (transient resource, owned by the task)
		DescriptorSet& ds = task.add_descriptor_set(set_layout);
		ds.bind_buffer(0, *input_buffer);
		ds.bind_buffer(1, *local_results_buffer);
		ds.write();

		// begin command buffer recording
		CommandBuffer& cb = task.get_command_buffer();
		cb.begin_recording();
		cb.bind_pipeline(pipeline);
		cb.bind_descriptor_set(ds, pipeline);
		cb.bind_push_constants(constants, pipeline);

		// first iteration: copy source data to input buffer
		if (iteration == 0) {
			cb.add_buffer_memory_barrier(this->get_buffer(), VK_ACCESS_2_SHADER_WRITE_BIT | VK_ACCESS_2_SHADER_READ_BIT | VK_ACCESS_2_TRANSFER_WRITE_BIT | VK_ACCESS_2_TRANSFER_READ_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT | VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
			cb.record_barriers();
			cb.copy_buffer(this->get_buffer(), *input_buffer);
			cb.add_buffer_memory_barrier(*input_buffer, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_SHADER_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT);
			cb.record_barriers();
		}

		// pipeline dispatch
		cb.dispatch(pipeline, elements_A, 1, 1);

		// final iteration
		if (num_workgroups == 1) {
			// copy final result to staging buffer to allow host visibility
			cb.add_buffer_memory_barrier<float_t>(*local_results_buffer, VK_ACCESS_2_SHADER_WRITE_BIT, VK_ACCESS_2_TRANSFER_READ_BIT, VK_PIPELINE_STAGE_2_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT);
			cb.record_barriers();
			cb.copy_buffer(*local_results_buffer, final_result_staging_buffer, sizeof(float_t), 0, 0);
			cb.add_buffer_memory_barrier(final_result_staging_buffer, VK_ACCESS_2_TRANSFER_WRITE_BIT, VK_ACCESS_2_HOST_READ_BIT, VK_PIPELINE_STAGE_2_TRANSFER_BIT, VK_PIPELINE_STAGE_2_HOST_BIT);
			cb.record_barriers();
		}

		// all other iterations
		else {
			input_buffer = input_buffer == &buffer_A ? &buffer_B : &buffer_A;					// ping-pong swap
			local_results_buffer = local_results_buffer == &buffer_A ? &buffer_B : &buffer_A;	// "   "   "
		}

		cb.end_recording();
		task.timeline_sync(*timeline_semaphore);

		// ensure that the final result copy has finished before reading back from the staging buffer
		if (num_workgroups == 1) {
			task.submit(1e09); // = wait for fence
		}
		else {
			task.submit();
		}

		elements_A = num_workgroups;
		num_workgroups = (elements_A + workgroup_size_1d - 1) / workgroup_size_1d;
		iteration++;

	} while (num_workgroups > 1);

	main_task.get_command_buffer(); // empty command buffer, just to trigger a fence signaling completion
	uint64_t finished_counter = main_task.timeline_sync(*timeline_semaphore);
	this->set_tasks_finished_semaphore_counter(finished_counter);
	main_task.submit(5e09);
	float_t result = final_result_staging_buffer.read_element(0);
	return result;
}

// returns the arithmetic mean of all values of the NGrid
float_t NGrid::mean() const {
	return this->sum() / this->elements;
}

// returns the median of all values the NGrid;
// NGrid must be 1d
float_t NGrid::median() const {

	// confirm 1d array
	if (this->dimensions > 1) {
		Log::warning("invalid usage of method NGrid::median(), underlying array must be 1d but has ", this->dimensions, " dimensions");
		return 0.0f;
	}

	NGrid sorted = this->sort();

	// odd number of elements
	if (this->elements % 2) {
		return sorted.get(elements / 2);
	}
	// even number of elements
	else {
		return (sorted.get(elements / 2 - 1) + sorted.get(elements / 2)) / 2;
	}
}

// returns the variance of all values of a vector, matrix or array
// as a floating point number;
// use 'true' for the sample_var parameter to query the sample variance;
// if 'false' the population variance will be returned instead
float_t NGrid::var(bool sample_var) const {
	float_t mean = this->sum() / this->elements;
	NGrid mdev2 = (*this - mean).pow();
	float_t mdev2_sum = mdev2.sum();
	float variance = sample_var ? mdev2_sum / (this->elements - 1) : mdev2_sum / this->elements;

	// NAN/INF check
	if (std::isinf(variance) || std::isnan(variance)) {
		// infinite results may be the consequence of summing up many very large numbers,
		// which may happen because the mean deviations are squared before calculting the sum;
		// therefore, let's try to divide elementwise by N (or N-1) first, before summing up:
		if (sample_var) {
			variance = (mdev2 / (this->elements - 1)).sum();
		}
		else {
			variance = (mdev2 / this->elements).sum();
		}
	}

	return variance;
}

// returns the standard deviation of all values a the vector, matrix or array
float_t NGrid::stdev() const {
	return std::sqrt(this->var());
}

// returns the skewness (sample or population) of all data of the NGrid
float_t NGrid::skew(const bool sample_skew) const {

	// for formula explanation see: https://en.wikipedia.org/wiki/Skewness

	// get the mean
	float_t n = this->elements;
	float_t mean = this->mean();

	// get mean deviations
	NGrid mdev = *this - mean;

	// get third sample moment
	float_t m3 = (mdev.pow(3)).sum() / n;

	// NAN/INF check
	if (std::isinf(m3) || std::isnan(m3)) {
		// infinite results may be the consequence of summing up many very large numbers,
		// which may happen because the mean deviations are raised to the third power before calculting the sum;
		// therefore, let's try to divide elementwise by N first, before summing up:
		m3 = (mdev.pow(3) / n).sum();
	}

	// get standard deviation
	float_t s = std::pow(mdev.pow(2).sum() / (n - 1), 2);

	// NAN/INF check
	if (std::isinf(s) || std::isnan(s)) {
		s = std::pow((mdev.pow(2) / (n - 1)).sum(), 2);
	}

	// get b1 (population skewness estimator)
	float_t b1 = m3 / std::pow(s, 3);

	// in case of the population skewness we are done here
	if (!sample_skew) {
		return b1;
	}
	// else: return sample skewness
	else {
		float_t G1 = ((n * n) / ((n - 1) * (n - 2))) * b1;
		return G1;
	}
}

// returns the kurtosis of all elements of the NGrid
float_t NGrid::kurt(const bool sample_kurt) const {

	// for formula explanation see: https://en.wikipedia.org/wiki/Kurtosis

	// get the mean
	float_t n = this->elements;
	float_t mean = this->mean();

	// get mean deviations
	NGrid mdev = *this - mean;

	// get second and fourth sample moment
	float_t m2 = (mdev.pow(2)).sum() / n;
	float_t m4 = (mdev.pow(4)).sum() / n;

	// NAN/INF check
	if (std::isinf(m2) || std::isnan(m2)) {
		// infinite results may be the consequence of summing up many very large numbers,
		// which may happen because the mean deviations are raised to the power before calculting the sum;
		// therefore, let's try to divide elementwise by N first, before summing up:
		m2 = (mdev.pow(2) / n).sum();
	}
	if (std::isinf(m4) || std::isnan(m4)) {
		m4 = (mdev.pow(4) / n).sum();
	}

	// calculate sample kurtosis
	float_t g2 = m4 / std::pow(m2, 2) - 3.0f;

	// in case of the sample kurtosis (biased estimator) we are done heere
	if (sample_kurt) {
		return g2;
	}
	// else: calculate population kurtosis (unbiased estimator)
	else {
		float_t G2 = ((n - 1) / ((n - 2) * (n - 3))) * ((n + 1) * g2 + 6);
		return G2;
	}
}

